<?php require_once 'auth.php';requiereRol('cliente');$id=(int)$_SESSION['idUsuario'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['nombre']??'');$es=trim($_POST['especie']??'');$ra=trim($_POST['raza']??'');$edad=(int)($_POST['edad']??0);$peso=(float)($_POST['peso']??0);$obs=trim($_POST['observaciones']??'');if($n&&$es){$q=$conexion->prepare('INSERT INTO mascotas(idUsuario,nombre,especie,raza,edad,peso,observaciones) VALUES(?,?,?,?,?,?,?)');$q->execute([$id,$n,$es,$ra,$edad,$peso,$obs]);$msg='Mascota registrada correctamente.';}}$q=$conexion->prepare('SELECT * FROM mascotas WHERE idUsuario=? ORDER BY idMascota DESC');$q->execute([$id]);$rows=$q->fetchAll();encabezado('Mis mascotas');alerta($msg);?><div class="form-card"><h2>Registrar mascota</h2><form method="post" class="form-grid"><label>Nombre<input name="nombre" required></label><label>Especie<select name="especie"><option>Perro</option><option>Gato</option><option>Ave</option><option>Otro</option></select></label><label>Raza<input name="raza"></label><label>Edad (años)<input type="number" name="edad" min="0" value="0"></label><label>Peso (kg)<input type="number" step="0.1" name="peso" min="0"></label><label>Observaciones<input name="observaciones"></label><button class="btn">Guardar mascota</button></form></div><h2>Mis mascotas</h2><div class="table-wrap"><table><tr><th>Nombre</th><th>Especie</th><th>Raza</th><th>Edad</th><th>Peso</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['especie'])?></td><td><?=e($r['raza'])?></td><td><?=e($r['edad'])?></td><td><?=e($r['peso'])?> kg</td></tr><?php endforeach;?></table></div><?php pie();?>